const libFableServiceProviderBase = require('fable-serviceproviderbase');

/**
 * PictService-Flow-PanelManager
 *
 * Manages the lifecycle of properties panels in the flow diagram:
 * opening, closing, toggling, and position updates for panels
 * associated with flow nodes.
 */
class PictServiceFlowPanelManager extends libFableServiceProviderBase
{
	constructor(pFable, pOptions, pServiceHash)
	{
		super(pFable, pOptions, pServiceHash);

		this.serviceType = 'PictServiceFlowPanelManager';

		this._FlowView = (pOptions && pOptions.FlowView) ? pOptions.FlowView : null;
	}

	/**
	 * Pick an initial panel position that keeps the panel inside the currently visible viewport when it
	 * can. The default is to the right of the node; if that would push the panel off the right edge of
	 * the visible area (a node near the edge -- the panel would clip), flip it to the node's left. The Y
	 * is clamped so the panel does not hang off the top or bottom. Falls back to the right-of-node
	 * placement when the viewport bounds are not measurable (no SVG element, not yet rendered, or a
	 * server-side render with no CTM). The panel is draggable, so this is only the opening position.
	 * @param {Object} pNode - The node the panel anchors to (graph-space X/Y/Width)
	 * @param {number} pWidth - The panel width (graph units)
	 * @param {number} pHeight - The panel height (graph units)
	 * @returns {{X: number, Y: number}}
	 */
	_computePanelPosition(pNode, pWidth, pHeight)
	{
		let tmpGap = 30;
		let tmpRightX = pNode.X + pNode.Width + tmpGap;
		let tmpDefault = { X: tmpRightX, Y: pNode.Y };

		let tmpViewport = this._FlowView ? this._FlowView._ViewportManager : null;
		let tmpSVG = this._FlowView ? this._FlowView._SVGElement : null;
		if (!tmpViewport || !tmpSVG || typeof tmpSVG.getBoundingClientRect !== 'function' || typeof tmpViewport.screenToSVGCoords !== 'function')
		{
			return tmpDefault;
		}

		let tmpRect = tmpSVG.getBoundingClientRect();
		if (!tmpRect || !(tmpRect.width > 0) || !(tmpRect.height > 0)) { return tmpDefault; }

		// The visible canvas in graph coordinates (screenToSVGCoords already undoes pan + zoom).
		let tmpTopLeft = tmpViewport.screenToSVGCoords(tmpRect.left, tmpRect.top);
		let tmpBottomRight = tmpViewport.screenToSVGCoords(tmpRect.right, tmpRect.bottom);
		let tmpVisLeft = Math.min(tmpTopLeft.x, tmpBottomRight.x);
		let tmpVisRight = Math.max(tmpTopLeft.x, tmpBottomRight.x);
		let tmpVisTop = Math.min(tmpTopLeft.y, tmpBottomRight.y);
		let tmpVisBottom = Math.max(tmpTopLeft.y, tmpBottomRight.y);

		// Side selection: right unless it would clip; then the node's left if the panel fits there, else
		// whichever side has more room.
		let tmpX = tmpRightX;
		if (tmpRightX + pWidth > tmpVisRight)
		{
			let tmpLeftX = pNode.X - tmpGap - pWidth;
			if (tmpLeftX >= tmpVisLeft)
			{
				tmpX = tmpLeftX;
			}
			else
			{
				let tmpRoomRight = tmpVisRight - tmpRightX;
				let tmpRoomLeft = (pNode.X - tmpGap) - tmpVisLeft;
				tmpX = (tmpRoomLeft > tmpRoomRight) ? tmpLeftX : tmpRightX;
			}
		}
		// Final clamp into the visible band, but only when the panel actually fits in it (otherwise a
		// panel wider than the viewport would get pinned uselessly to the left edge).
		if ((tmpVisRight - tmpVisLeft) > pWidth) { tmpX = Math.max(tmpVisLeft, Math.min(tmpX, tmpVisRight - pWidth)); }

		let tmpY = pNode.Y;
		if ((tmpVisBottom - tmpVisTop) > pHeight) { tmpY = Math.max(tmpVisTop, Math.min(tmpY, tmpVisBottom - pHeight)); }

		return { X: tmpX, Y: tmpY };
	}

	/**
	 * Open a properties panel for a node.
	 * @param {string} pNodeHash - The hash of the node to open a panel for
	 * @returns {Object|false} The panel data, or false if the node was not found
	 */
	openPanel(pNodeHash)
	{
		let tmpNode = this._FlowView.getNode(pNodeHash);
		if (!tmpNode) return false;

		let tmpNodeTypeConfig = this._FlowView._NodeTypeProvider.getNodeType(tmpNode.Type);
		if (!tmpNodeTypeConfig) return false;

		// Check if a panel is already open for this node
		let tmpExisting = this._FlowView._FlowData.OpenPanels.find((pPanel) => pPanel.NodeHash === pNodeHash);
		if (tmpExisting) return tmpExisting;

		let tmpPanelConfig = tmpNodeTypeConfig.PropertiesPanel;
		let tmpPanelHash = `panel-${this.fable.getUUID()}`;
		let tmpWidth, tmpHeight, tmpPanelType, tmpTitle;

		if (tmpPanelConfig)
		{
			tmpWidth = tmpPanelConfig.DefaultWidth || 300;
			tmpHeight = tmpPanelConfig.DefaultHeight || 200;
			tmpPanelType = tmpPanelConfig.PanelType || 'Base';
			tmpTitle = tmpPanelConfig.Title || tmpNodeTypeConfig.Label || 'Properties';
		}
		else
		{
			// No PropertiesPanel configured — open an auto-generated info panel
			tmpWidth = 240;
			tmpHeight = 180;
			tmpPanelType = 'Info';
			tmpTitle = tmpNodeTypeConfig.Label || tmpNode.Title || 'Node Info';
		}

		let tmpPanelPosition = this._computePanelPosition(tmpNode, tmpWidth, tmpHeight);
		let tmpPanelData =
		{
			Hash: tmpPanelHash,
			NodeHash: pNodeHash,
			PanelType: tmpPanelType,
			Title: tmpTitle,
			X: tmpPanelPosition.X,
			Y: tmpPanelPosition.Y,
			Width: tmpWidth,
			Height: tmpHeight
		};

		this._FlowView._FlowData.OpenPanels.push(tmpPanelData);
		this._FlowView.renderFlow();
		this._FlowView.marshalFromView();

		if (this._FlowView._EventHandlerProvider)
		{
			this._FlowView._EventHandlerProvider.fireEvent('onPanelOpened', tmpPanelData);
			this._FlowView._EventHandlerProvider.fireEvent('onFlowChanged', this._FlowView._FlowData);
		}

		return tmpPanelData;
	}

	/**
	 * Close a properties panel by panel hash.
	 * @param {string} pPanelHash
	 * @returns {boolean}
	 */
	closePanel(pPanelHash)
	{
		let tmpIndex = this._FlowView._FlowData.OpenPanels.findIndex((pPanel) => pPanel.Hash === pPanelHash);
		if (tmpIndex < 0) return false;

		let tmpRemovedPanel = this._FlowView._FlowData.OpenPanels.splice(tmpIndex, 1)[0];

		// Clean up the panel instance
		if (this._FlowView._PropertiesPanelView)
		{
			this._FlowView._PropertiesPanelView.destroyPanel(pPanelHash);
		}

		this._FlowView.renderFlow();
		this._FlowView.marshalFromView();

		if (this._FlowView._EventHandlerProvider)
		{
			this._FlowView._EventHandlerProvider.fireEvent('onPanelClosed', tmpRemovedPanel);
			this._FlowView._EventHandlerProvider.fireEvent('onFlowChanged', this._FlowView._FlowData);
		}

		return true;
	}

	/**
	 * Close all panels for a given node.
	 * @param {string} pNodeHash
	 * @returns {boolean}
	 */
	closePanelForNode(pNodeHash)
	{
		let tmpPanelsToClose = this._FlowView._FlowData.OpenPanels.filter((pPanel) => pPanel.NodeHash === pNodeHash);
		if (tmpPanelsToClose.length === 0) return false;

		for (let i = 0; i < tmpPanelsToClose.length; i++)
		{
			let tmpIndex = this._FlowView._FlowData.OpenPanels.indexOf(tmpPanelsToClose[i]);
			if (tmpIndex >= 0)
			{
				this._FlowView._FlowData.OpenPanels.splice(tmpIndex, 1);
			}
			if (this._FlowView._PropertiesPanelView)
			{
				this._FlowView._PropertiesPanelView.destroyPanel(tmpPanelsToClose[i].Hash);
			}
		}

		return true;
	}

	/**
	 * Toggle a properties panel for a node (open if closed, close if open).
	 * @param {string} pNodeHash
	 * @returns {Object|false}
	 */
	togglePanel(pNodeHash)
	{
		let tmpExisting = this._FlowView._FlowData.OpenPanels.find((pPanel) => pPanel.NodeHash === pNodeHash);
		if (tmpExisting)
		{
			this.closePanel(tmpExisting.Hash);
			return false;
		}
		return this.openPanel(pNodeHash);
	}

	/**
	 * Open a properties panel for a connection (edge). The panel config comes from the FlowView's
	 * ConnectionPropertiesPanel option (connections are not typed, so one config serves them all);
	 * the panel is placed near the connection's midpoint and tethers to it. Returns false when no
	 * ConnectionPropertiesPanel is configured, so a host that has not opted in keeps the default
	 * edge behavior (double-click adds a bezier handle).
	 * @param {string} pConnectionHash
	 * @returns {Object|false} The panel data, or false
	 */
	openConnectionPanel(pConnectionHash)
	{
		let tmpConnection = this._FlowView.getConnection(pConnectionHash);
		if (!tmpConnection) return false;

		let tmpPanelConfig = this._FlowView.options.ConnectionPropertiesPanel;
		if (!tmpPanelConfig) return false;

		let tmpExisting = this._FlowView._FlowData.OpenPanels.find((pPanel) => pPanel.ConnectionHash === pConnectionHash);
		if (tmpExisting) return tmpExisting;

		let tmpMidpoint = this._FlowView.getConnectionMidpoint(pConnectionHash) || { x: 0, y: 0 };
		let tmpWidth = tmpPanelConfig.DefaultWidth || 300;
		let tmpHeight = tmpPanelConfig.DefaultHeight || 200;

		let tmpPanelData =
		{
			Hash: `panel-${this.fable.getUUID()}`,
			ConnectionHash: pConnectionHash,
			NodeHash: null,
			PanelType: tmpPanelConfig.PanelType || 'Base',
			Title: tmpPanelConfig.Title || 'Connection',
			X: tmpMidpoint.x + 40,
			Y: tmpMidpoint.y + 20,
			Width: tmpWidth,
			Height: tmpHeight
		};

		this._FlowView._FlowData.OpenPanels.push(tmpPanelData);
		this._FlowView.renderFlow();
		this._FlowView.marshalFromView();

		if (this._FlowView._EventHandlerProvider)
		{
			this._FlowView._EventHandlerProvider.fireEvent('onPanelOpened', tmpPanelData);
			this._FlowView._EventHandlerProvider.fireEvent('onFlowChanged', this._FlowView._FlowData);
		}

		return tmpPanelData;
	}

	/**
	 * Toggle a properties panel for a connection (open if closed, close if open).
	 * @param {string} pConnectionHash
	 * @returns {Object|false}
	 */
	toggleConnectionPanel(pConnectionHash)
	{
		let tmpExisting = this._FlowView._FlowData.OpenPanels.find((pPanel) => pPanel.ConnectionHash === pConnectionHash);
		if (tmpExisting)
		{
			this.closePanel(tmpExisting.Hash);
			return false;
		}
		return this.openConnectionPanel(pConnectionHash);
	}

	/**
	 * Close all panels for a given connection.
	 * @param {string} pConnectionHash
	 * @returns {boolean}
	 */
	closePanelForConnection(pConnectionHash)
	{
		let tmpPanelsToClose = this._FlowView._FlowData.OpenPanels.filter((pPanel) => pPanel.ConnectionHash === pConnectionHash);
		if (tmpPanelsToClose.length === 0) return false;

		for (let i = 0; i < tmpPanelsToClose.length; i++)
		{
			let tmpIndex = this._FlowView._FlowData.OpenPanels.indexOf(tmpPanelsToClose[i]);
			if (tmpIndex >= 0)
			{
				this._FlowView._FlowData.OpenPanels.splice(tmpIndex, 1);
			}
			if (this._FlowView._PropertiesPanelView)
			{
				this._FlowView._PropertiesPanelView.destroyPanel(tmpPanelsToClose[i].Hash);
			}
		}

		return true;
	}

	/**
	 * Update a panel's position (for drag).
	 * @param {string} pPanelHash
	 * @param {number} pX
	 * @param {number} pY
	 */
	updatePanelPosition(pPanelHash, pX, pY)
	{
		let tmpPanel = this._FlowView._FlowData.OpenPanels.find((pPanel) => pPanel.Hash === pPanelHash);
		if (!tmpPanel) return;

		tmpPanel.X = pX;
		tmpPanel.Y = pY;

		// Reset tether handle positions when panel moves
		this._FlowView._resetHandlesForPanel(pPanelHash);

		// Update the foreignObject position directly for smooth dragging
		if (this._FlowView._PanelsLayer)
		{
			let tmpFO = this._FlowView._PanelsLayer.querySelector(`[data-panel-hash="${pPanelHash}"]`);
			if (tmpFO)
			{
				tmpFO.setAttribute('x', String(pX));
				tmpFO.setAttribute('y', String(pY));
			}
		}

		// Update the tether for this panel. A node panel refreshes just its node's tethers; a
		// connection panel has no node, so reconcile the panels layer (redraws all tethers, which
		// is where the connection-midpoint tether is recomputed).
		if (tmpPanel.ConnectionHash)
		{
			if (this._FlowView._PropertiesPanelView && this._FlowView._PanelsLayer && this._FlowView._TethersLayer)
			{
				this._FlowView._PropertiesPanelView.renderPanels(this._FlowView._FlowData.OpenPanels, this._FlowView._PanelsLayer, this._FlowView._TethersLayer, this._FlowView._FlowData.ViewState.SelectedTetherHash);
			}
		}
		else
		{
			this._FlowView._renderTethersForNode(tmpPanel.NodeHash);
		}
	}
}

module.exports = PictServiceFlowPanelManager;
